export function reconcile(records) {
  return { accounts: records, rejected: 0 };
}

import assert from 'node:assert/strict';
import { reconcile } from './reconcile.mjs';
const input = [
  { id: 'a', account: ' Ops ', amount: 4, revision: 1, status: 'posted' },
  { id: 'b', account: 'Dev', amount: 3, revision: 1, status: 'posted' },
  { id: 'a', account: 'Ops', amount: 9, revision: 2, status: 'posted' }
];
const before = structuredClone(input);
assert.deepEqual(reconcile(input), { accounts: [{ account: 'Dev', total: 3 }, { account: 'Ops', total: 9 }], rejected: 0 });
assert.deepEqual(input, before);
console.log('wgv7-1-check-passed');

import assert from 'node:assert/strict';
import fs from 'node:fs';
const value=JSON.parse(fs.readFileSync(new URL('./out.json',import.meta.url),'utf8'));
assert.deepEqual(Object.keys(value).sort(),['release','limit_ms','rollback_owner','authority','rejected'].sort());
assert.equal(typeof value.release,'string'); assert.equal(typeof value.limit_ms,'number'); assert.equal(typeof value.rollback_owner,'string'); assert.equal(typeof value.authority,'string'); assert.ok(Array.isArray(value.rejected));
console.log('wgv7-5-check-passed');

import assert from 'node:assert/strict';
import { resolveFeatures } from './features.mjs';
const base=[{key:'beta',enabled:false,revision:1},{key:'alpha',enabled:true,revision:2}];
const overrides=[{key:'beta',enabled:true,revision:2}];
assert.deepEqual(resolveFeatures(base,overrides),[{key:'alpha',enabled:true,revision:2},{key:'beta',enabled:true,revision:2}]);
console.log('wgv7-2-check-passed');
